cat > /tmp/pmtest.mjs <<'EOF'
import picomatch from 'picomatch';
const norm = p => p.replace(/\\/g,'/').replace(/^\.\//,'');
const wts = p => { const t = p.replace(/\/+$/,''); return t.length>0?t:p; };
function matcherFor(raw){
  const pattern = wts(norm(raw));
  const patterns = /[*?[\]{}!]/.test(pattern) ? [pattern] : [pattern, `${pattern}/**`, `**/${pattern}`, `**/${pattern}/**`];
  return {patterns, m: picomatch(patterns,{dot:true})};
}
const paths = ['benchmark','benchmark/a.json','benchmark/x/y/z.json','src/benchmark/a.json','a/b/benchmark','secrets','secrets/key.pem','deep/secrets/key.pem','benchmarks/a.json','mybenchmark/a.json','node_modules/.bin/x','docs/evidence/FERRET-DOES-IT-HELP.md'];
for (const raw of ['benchmark','benchmark/','benchmark/**','secrets/','node_modules','docs/evidence/FERRET-DOES-IT-HELP.md','**','/']){
  const {patterns,m} = matcherFor(raw);
  console.log(`\nPATTERN ${JSON.stringify(raw)} -> ${JSON.stringify(patterns)}`);
  for (const p of paths) if (m(p)) console.log('   MATCH', p);
}
EOF
node /tmp/pmtest.mjs

